Suggestion: so this is what I had in mind:

```rs
/// Search for all files in the current working directory with the extension `ext`,
/// read their contents and count the
/// number of regex matches with a given expression (re).
#[track_caller]
pub fn count_regex_matches_in_files_with_extension(
    re: &regex::Regex,
    ext: &str,
) -> usize {
    use walkdir::{DirEntry, WalkDir};

    let walker = WalkDir::new(cwd()).into_iter();

    fn is_hidden(entry: &DirEntry) -> bool {
        entry.file_name().to_str().map(|s| s.starts_with(".")).unwrap_or(false)
    }

    let mut count = 0;

    for entry in walker.filter_entry(|e| !is_hidden(e)) {
        let entry = entry.unwrap("failed to get DirEntry");
        if !entry.path().is_file() {
            continue;
        }

        if !entry.path().extension().is_some_and(|e| e == ext) {
            continue;
        }

        let content = fs_wrapper::read(entry.path());
        count += content.lines().filter(|line| re.is_match(line)).count();
    }

    count
}
```

